class Solution:
    def getAverages(self, nums: list[int], k: int) -> list[int]:
        n = len(nums)
        ans = [-1] * n
        window_size = 2 * k + 1

        if window_size > n:
            return ans

        curr_sum = sum(nums[:window_size])
        ans[k] = curr_sum // window_size

        for i in range(k + 1, n - k):
            curr_sum += nums[i + k] - nums[i - k - 1]
            ans[i] = curr_sum // window_size

        return ans

#include <vector>
#include <numeric>

class Solution {
public:
    std::vector<int> getAverages(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> ans(n, -1);
        long long windowSize = 2LL * k + 1;

        if (windowSize > n) return ans;

        long long currSum = 0;
        for (int i = 0; i < windowSize; ++i) {
            currSum += nums[i];
        }
        ans[k] = currSum / windowSize;

        for (int i = k + 1; i < n - k; ++i) {
            currSum += nums[i + k] - nums[i - k - 1];
            ans[i] = currSum / windowSize;
        }

        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public int[] getAverages(int[] nums, int k) {
        int n = nums.length;
        int[] ans = new int[n];
        Arrays.fill(ans, -1);

        long windowSize = 2L * k + 1;
        if (windowSize > n) return ans;

        long currSum = 0;
        for (int i = 0; i < windowSize; i++) {
            currSum += nums[i];
        }
        ans[k] = (int) (currSum / windowSize);

        for (int i = k + 1; i < n - k; i++) {
            currSum += nums[i + k] - nums[i - k - 1];
            ans[i] = (int) (currSum / windowSize);
        }

        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var getAverages = function(nums, k) {
    const n = nums.length;
    const ans = new Array(n).fill(-1);
    const windowSize = 2 * k + 1;

    if (windowSize > n) return ans;

    let currSum = 0;
    for (let i = 0; i < windowSize; i++) {
        currSum += nums[i];
    }
    ans[k] = Math.floor(currSum / windowSize);

    for (let i = k + 1; i < n - k; i++) {
        currSum += nums[i + k] - nums[i - k - 1];
        ans[i] = Math.floor(currSum / windowSize);
    }

    return ans;
};
